#### dynamic programming with memoization

```cpp
#include <string>
#include <vector>
#include <unordered_map>

bool canConcat(std::string str, std::vector<std::string> words, std::unordered_map<std::string, bool> &memo) {
  if (memo.count(str) > 0) {
    return memo[str];
  }

  if (str.length() == 0) {
    return true;
  }

  for (std::string word : words) {
    if (str.find(word) == 0) {
      std::string suffix = str.substr(word.length());
      if (canConcat(suffix, words, memo)) {
        memo[str] = true;
        return true;
      }
    }
  }

  memo[str] = false;
  return false;
}

bool canConcat(std::string str, std::vector<std::string> words) {
  std::unordered_map<std::string, bool> memo;
  return canConcat(str, words, memo);
}
```

- s = length of string
- w = # of words
- Time: ~O(sw)
- Space: O(s)
